import { useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { exportToExcel, exportToPdf } from "@/lib/reportExport";
import * as XLSX from "xlsx";
import { startLogin } from "@/const";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import { Activity, ArrowDownLeft, ArrowUpRight, BarChart3, Bell, BookOpen, Boxes, BriefcaseBusiness, Calculator, ChevronLeft, CircleDollarSign, FileBarChart, FilePlus2, HelpCircle, LayoutDashboard, LogOut, Menu, Package, PanelRight, Plus, ReceiptText, ScanBarcode, Search, Settings2, ShoppingCart, Sparkles, UsersRound, WalletCards, X } from "lucide-react";
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, PieChart, Pie, Cell, Legend } from "recharts";

const nav = [
  { id: "dashboard", label: "لوحة التحكم", icon: LayoutDashboard },
  { id: "accounting", label: "المحاسبة", icon: Calculator },
  { id: "sales", label: "المبيعات والفواتير", icon: ReceiptText },
  { id: "purchases", label: "المشتريات", icon: ShoppingCart },
  { id: "parties", label: "العملاء والموردون", icon: UsersRound },
  { id: "inventory", label: "المخزون", icon: Boxes },
  { id: "hr", label: "الموارد البشرية", icon: BriefcaseBusiness },
  { id: "pos", label: "نقطة البيع", icon: ScanBarcode },
  { id: "reports", label: "التقارير المالية", icon: FileBarChart },
  { id: "assistant", label: "المساعد الذكي", icon: Sparkles },
  { id: "settings", label: "الإعدادات والاستيراد", icon: Settings2 },
];

const money = (value: number) => new Intl.NumberFormat("ar-SA", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value) + " ر.س";

function MetricCard({ title, value, caption, icon: Icon, tone }: { title: string; value: string; caption: string; icon: typeof CircleDollarSign; tone: string }) {
  return <Card className="metric-card"><CardContent className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-sm text-muted-foreground">{title}</p><p className="mt-2 text-2xl font-black tracking-tight">{value}</p><p className="mt-2 text-xs text-muted-foreground">{caption}</p></div><div className={`metric-icon ${tone}`}><Icon className="h-5 w-5" /></div></div></CardContent></Card>;
}

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [active, setActive] = useState("dashboard");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showQuick, setShowQuick] = useState(false);
  const { data: summary } = trpc.dashboard.summary.useQuery(undefined, { enabled: isAuthenticated });
  const { data: notifications } = trpc.dashboard.notifications.useQuery(undefined, { enabled: isAuthenticated });
  const { data: accounts = [] } = trpc.accounts.list.useQuery(undefined, { enabled: isAuthenticated && active === "accounting" });
  const { data: products = [] } = trpc.products.list.useQuery(undefined, { enabled: isAuthenticated && (active === "inventory" || active === "pos") });
  const { data: parties = [] } = trpc.parties.list.useQuery(undefined, { enabled: isAuthenticated && (active === "parties" || active === "reports") });
  const { data: employees = [] } = trpc.employees.list.useQuery(undefined, { enabled: isAuthenticated && active === "hr" });
  const { data: invoices = [] } = trpc.invoices.list.useQuery(undefined, { enabled: isAuthenticated && (active === "sales" || active === "purchases" || active === "reports") });
  const { data: currencies = [] } = trpc.currencies.list.useQuery(undefined, { enabled: isAuthenticated && (active === "reports" || active === "settings" || active === "pos") });
  const { data: journals = [] } = trpc.journals.list.useQuery(undefined, { enabled: isAuthenticated && active === "accounting" });
  const createAccount = trpc.accounts.create.useMutation({ onSuccess: () => { toast.success("تمت إضافة الحساب"); setShowQuick(false); } });
  const createProduct = trpc.products.create.useMutation({ onSuccess: () => { toast.success("تمت إضافة المنتج"); setShowQuick(false); } });
  const createParty = trpc.parties.create.useMutation({ onSuccess: () => { toast.success("تمت إضافة السجل"); setShowQuick(false); } });
  const lowStock = useMemo(() => products.filter(p => Number(p.quantity) < Number(p.minQuantity)), [products]);

  if (loading) return <div className="min-h-screen grid place-items-center bg-[#f6f8fb] text-muted-foreground">جارٍ تحميل النظام...</div>;
  if (!isAuthenticated) return <div className="min-h-screen grid place-items-center bg-[#f6f8fb] p-6"><Card className="max-w-md text-center"><CardHeader><div className="brand-mark mx-auto">م</div><CardTitle className="text-2xl">منصة مدار المالية</CardTitle></CardHeader><CardContent><p className="mb-6 text-muted-foreground">نظام عربي متكامل لإدارة المحاسبة والمبيعات والمخزون والأعمال.</p><Button className="w-full" onClick={() => startLogin()}>تسجيل الدخول للمتابعة</Button></CardContent></Card></div>;

  const selectedLabel = nav.find(item => item.id === active)?.label ?? "لوحة التحكم";
  return <div dir="rtl" className="min-h-screen bg-[#f6f8fb] text-slate-900">
    <aside className={`app-sidebar ${sidebarOpen ? "open" : ""}`}>
      <div className="sidebar-head"><div className="brand-mark">م</div><div><p className="brand-name">مدار المالية</p><p className="brand-sub">نظام إدارة الأعمال</p></div><button className="mobile-close" onClick={() => setSidebarOpen(false)}><X /></button></div>
      <div className="company-switch"><div className="company-avatar">ش</div><div><p className="text-sm font-bold">شركة الشروق التجارية</p><p className="text-xs text-muted-foreground">السنة المالية 2026</p></div><ChevronLeft className="mr-auto h-4 w-4 text-muted-foreground" /></div>
      <p className="side-label">القائمة الرئيسية</p><nav className="space-y-1">{nav.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => { setActive(item.id); setSidebarOpen(false); }} className={`side-link ${active === item.id ? "active" : ""}`}><Icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{item.id === "assistant" && <span className="ai-dot" />}</button>; })}</nav>
      <div className="sidebar-bottom"><button className="side-link"><Settings2 className="h-[18px] w-[18px]" />الإعدادات</button><div className="user-row"><div className="user-avatar">{user?.name?.slice(0, 1) ?? "م"}</div><div className="min-w-0"><p className="truncate text-sm font-bold">{user?.name ?? "المستخدم"}</p><p className="text-xs text-muted-foreground">{user?.role === "admin" ? "مدير النظام" : "محاسب"}</p></div><button onClick={() => logout()} title="تسجيل الخروج"><LogOut className="h-4 w-4 text-muted-foreground" /></button></div></div>
    </aside>
    {sidebarOpen && <div className="sidebar-overlay" onClick={() => setSidebarOpen(false)} />}
    <main className="app-main">
      <header className="topbar"><div className="flex items-center gap-3"><button className="menu-button" onClick={() => setSidebarOpen(true)}><Menu /></button><div><p className="text-xs text-muted-foreground">الأربعاء، 13 أغسطس 2026</p><h1 className="text-xl font-black">{selectedLabel}</h1></div></div><div className="flex items-center gap-2"><button className="icon-button"><Search /></button><button className="icon-button relative"><Bell /><span className="notification-dot" /></button><Button className="quick-button" onClick={() => setShowQuick(true)}><Plus className="h-4 w-4" />إضافة جديدة</Button></div></header>
      <div className="page-content">
        {active === "dashboard" && <Dashboard summary={summary} notifications={notifications ?? []} onNavigate={setActive} />}
        {active === "accounting" && <ModulePage title="المحاسبة" description="إدارة شجرة الحسابات والقيود اليومية" icon={Calculator}><Tabs defaultValue="accounts" dir="rtl"><TabsList><TabsTrigger value="accounts">شجرة الحسابات</TabsTrigger><TabsTrigger value="journals">سندات القيد</TabsTrigger><TabsTrigger value="ledger">الأستاذ العام</TabsTrigger></TabsList><TabsContent value="accounts"><DataTable headers={["رمز الحساب", "اسم الحساب", "التصنيف", "الحالة"]} rows={accounts.map(a => [a.code, a.name, a.category === "asset" ? "أصول" : a.category === "liability" ? "التزامات" : a.category === "equity" ? "حقوق ملكية" : a.category === "revenue" ? "إيرادات" : "مصروفات", a.isActive ? "نشط" : "متوقف"])} empty="لم تتم إضافة حسابات بعد." /></TabsContent><TabsContent value="journals"><JournalEntryForm accounts={accounts} /><DataTable headers={["رقم القيد", "التاريخ", "البيان", "الحالة"]} rows={journals.map(j => [j.entryNumber, new Date(j.entryDate).toLocaleDateString("ar-SA"), j.description, j.status === "posted" ? "مرحّل" : "مسودة"])} empty="لا توجد قيود يومية بعد." /></TabsContent><TabsContent value="ledger"><ReportPlaceholder title="الأستاذ العام" text="اختر حساباً وفترة زمنية لعرض الحركات والأرصدة." /></TabsContent></Tabs></ModulePage>}
        {active === "sales" && <InvoiceModule title="فواتير المبيعات" type="sale" invoices={invoices.filter(i => i.type === "sale")} currencies={currencies} />}
        {active === "purchases" && <InvoiceModule title="فواتير المشتريات" type="purchase" invoices={invoices.filter(i => i.type === "purchase")} currencies={currencies} />}
        {active === "parties" && <ModulePage title="العملاء والموردون" description="ملفات الأطراف والأرصدة المستحقة" icon={UsersRound}><DataTable headers={["الاسم", "النوع", "الهاتف", "حد الائتمان", "الرصيد الافتتاحي"]} rows={parties.map(p => [p.name, p.type === "customer" ? "عميل" : "مورد", p.phone ?? "—", money(Number(p.creditLimit)), money(Number(p.openingBalance))])} empty="أضف أول عميل أو مورد من زر الإضافة الجديدة." /></ModulePage>}
        {active === "inventory" && <ModulePage title="المخزون" description="المنتجات وحركة الأصناف والتنبيهات" icon={Boxes}><div className="mb-5 grid gap-4 md:grid-cols-3"><MetricCard title="عدد الأصناف" value={String(products.length)} caption="الأصناف النشطة" icon={Package} tone="purple" /><MetricCard title="تحت الحد الأدنى" value={String(lowStock.length)} caption="تحتاج إلى إعادة طلب" icon={ArrowDownLeft} tone="orange" /><MetricCard title="قيمة المخزون" value={money(products.reduce((s, p) => s + Number(p.quantity) * Number(p.purchasePrice), 0))} caption="حسب تكلفة الشراء" icon={WalletCards} tone="green" /></div><StockMovePanel products={products} /><DataTable headers={["SKU", "المنتج", "الكمية", "الوحدة", "سعر البيع", "الحالة"]} rows={products.map(p => [p.sku, p.name, String(p.quantity), p.unit, money(Number(p.salePrice)), Number(p.quantity) < Number(p.minQuantity) ? "إعادة طلب" : "متوفر"])} empty="لم تتم إضافة منتجات بعد." /></ModulePage>}
        {active === "hr" && <ModulePage title="الموارد البشرية والرواتب" description="إدارة الموظفين وكشوف الرواتب" icon={BriefcaseBusiness}><PayrollPanel /><DataTable headers={["الرقم الوظيفي", "الموظف", "القسم", "الهاتف", "الراتب الأساسي"]} rows={employees.map(e => [e.employeeNumber, e.name, e.department ?? "—", e.phone ?? "—", money(Number(e.baseSalary))])} empty="لم تتم إضافة موظفين بعد." /></ModulePage>}
        {active === "pos" && <POS products={products} currencies={currencies} />}
        {active === "reports" && <EnhancedReports summary={summary} parties={parties} invoices={invoices} currencies={currencies} />}
        {active === "settings" && <SettingsAndImport currencies={currencies} />}
        {active === "assistant" && <Assistant />}
      </div>
    </main>
    {showQuick && <QuickAdd onClose={() => setShowQuick(false)} onAccount={values => createAccount.mutate(values)} onProduct={values => createProduct.mutate(values)} onParty={values => createParty.mutate(values)} />}
  </div>;
}

function Dashboard({ summary, notifications, onNavigate }: { summary?: { revenue: number; expenses: number; profit: number; receivables: number; invoiceCount: number; lowStockCount: number }; notifications: any[]; onNavigate: (id: string) => void }) {
  const s = summary ?? { revenue: 0, expenses: 0, profit: 0, receivables: 0, invoiceCount: 0, lowStockCount: 0 };
  return <><section className="welcome-panel"><div><p className="eyebrow">نظرة عامة على أعمالك</p><h2>مرحباً بك في <span>مدار المالية</span></h2><p>تابع أداء منشأتك واتخذ قراراتك بثقة من مكان واحد.</p></div><div className="welcome-art"><BarChart3 /><div className="bar bar-a" /><div className="bar bar-b" /><div className="bar bar-c" /></div></section><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard title="إجمالي الإيرادات" value={money(s.revenue)} caption="الفواتير المباعة المرحّلة" icon={ArrowUpRight} tone="green" /><MetricCard title="إجمالي المصروفات" value={money(s.expenses)} caption="الفواتير والمصروفات المسجلة" icon={ArrowDownLeft} tone="orange" /><MetricCard title="صافي الربح" value={money(s.profit)} caption="الإيرادات ناقص المصروفات" icon={CircleDollarSign} tone="purple" /><MetricCard title="المبالغ المستحقة" value={money(s.receivables)} caption="على العملاء حتى الآن" icon={WalletCards} tone="blue" /></div><div className="grid gap-5 xl:grid-cols-[1.35fr_0.65fr]"><Card><CardHeader className="flex-row items-center justify-between"><div><CardTitle>ملخص الأداء المالي</CardTitle><p className="mt-1 text-sm text-muted-foreground">مؤشرات الفترة الحالية</p></div><Button variant="outline" size="sm" onClick={() => onNavigate("reports")}>عرض التقارير <ChevronLeft className="mr-1 h-4 w-4" /></Button></CardHeader><CardContent><div className="chart-placeholder"><div className="chart-grid" /><div className="chart-line line-one" /><div className="chart-line line-two" /><div className="chart-legend"><span><i className="dot green-dot" />الإيرادات</span><span><i className="dot purple-dot" />المصروفات</span></div></div></CardContent></Card><Card><CardHeader><CardTitle>التنبيهات الأخيرة</CardTitle></CardHeader><CardContent className="space-y-3">{notifications.length ? notifications.slice(0, 4).map(n => <div key={n.id} className="alert-row"><div className="alert-icon"><Bell className="h-4 w-4" /></div><div><p className="text-sm font-bold">{n.title}</p><p className="text-xs text-muted-foreground">{n.message}</p></div></div>) : <div className="empty-state"><Bell className="h-8 w-8" /><p>لا توجد تنبيهات جديدة</p><span>ستظهر هنا تنبيهات الائتمان والمخزون والاستحقاقات.</span></div>}</CardContent></Card></div><div className="mt-5 grid gap-4 sm:grid-cols-3"><QuickTile icon={FilePlus2} title="سند قيد جديد" text="سجل حركة مالية" onClick={() => onNavigate("accounting")} /><QuickTile icon={ReceiptText} title="فاتورة مبيعات" text="أصدر فاتورة الآن" onClick={() => onNavigate("sales")} /><QuickTile icon={FileBarChart} title="تقرير مالي" text="حلل أداء منشأتك" onClick={() => onNavigate("reports")} /></div></>;
}

function ModulePage({ title, description, icon: Icon, children }: { title: string; description: string; icon: typeof Calculator; children: React.ReactNode }) { return <section><div className="section-heading"><div className="section-icon"><Icon /></div><div><h2>{title}</h2><p>{description}</p></div><Button className="mr-auto" onClick={() => toast.info("استخدم زر الإضافة الجديدة لإنشاء سجل") }><Plus className="h-4 w-4" />إضافة جديد</Button></div>{children}</section>; }
function DataTable({ headers, rows, empty }: { headers: string[]; rows: string[][]; empty: string }) { return <Card><CardContent className="p-0"><div className="overflow-x-auto"><table className="data-table"><thead><tr>{headers.map(h => <th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, i) => <tr key={i}>{row.map((cell, j) => <td key={j}>{j === row.length - 1 ? <Badge variant="outline">{cell}</Badge> : cell}</td>)}</tr>) : <tr><td colSpan={headers.length}><div className="empty-state py-14"><BookOpen className="h-8 w-8" /><p>{empty}</p></div></td></tr>}</tbody></table></div></CardContent></Card>; }
function JournalEntryForm({ accounts }: { accounts: any[] }) { const [entryNumber, setEntryNumber] = useState(`قيد-${Date.now().toString().slice(-6)}`); const [description, setDescription] = useState(""); const [lines, setLines] = useState([{ accountId: 0, debit: "", credit: "" }, { accountId: 0, debit: "", credit: "" }]); const create = trpc.journals.create.useMutation({ onSuccess: () => { toast.success("تم ترحيل القيد بنجاح"); setDescription(""); }, onError: error => toast.error(error.message) }); const debit = lines.reduce((s, l) => s + Number(l.debit || 0), 0); const credit = lines.reduce((s, l) => s + Number(l.credit || 0), 0); const balanced = Math.abs(debit - credit) < 0.005 && debit > 0; const updateLine = (index: number, key: string, value: string | number) => setLines(current => current.map((line, i) => i === index ? { ...line, [key]: value } : line)); return <Card className="journal-form"><CardHeader><CardTitle>سند قيد جديد</CardTitle><p className="text-sm text-muted-foreground">لا يمكن الترحيل قبل تساوي إجمالي المدين والدائن.</p></CardHeader><CardContent><div className="form-grid mb-4"><Input placeholder="رقم القيد" value={entryNumber} onChange={e => setEntryNumber(e.target.value)} /><Input placeholder="البيان" value={description} onChange={e => setDescription(e.target.value)} /></div><div className="journal-lines">{lines.map((line, index) => <div className="journal-line" key={index}><select value={line.accountId} onChange={e => updateLine(index, "accountId", Number(e.target.value))}><option value={0}>اختر الحساب</option>{accounts.map(account => <option key={account.id} value={account.id}>{account.code} — {account.name}</option>)}</select><Input type="number" placeholder="مدين" value={line.debit} onChange={e => updateLine(index, "debit", e.target.value)} /><Input type="number" placeholder="دائن" value={line.credit} onChange={e => updateLine(index, "credit", e.target.value)} /></div>)}</div><div className="journal-actions"><Button variant="outline" onClick={() => setLines(current => [...current, { accountId: 0, debit: "", credit: "" }])}><Plus className="h-4 w-4" />سطر جديد</Button><div className={`journal-total ${balanced ? "is-balanced" : ""}`}><span>مدين: <strong>{money(debit)}</strong></span><span>دائن: <strong>{money(credit)}</strong></span><Badge variant="outline">{balanced ? "متوازن" : "غير متوازن"}</Badge></div><Button disabled={!balanced || !description.trim() || create.isPending} onClick={() => create.mutate({ entryNumber, entryDate: new Date(), description, lines })}>ترحيل القيد</Button></div></CardContent></Card>; }

function InvoiceModule({ title, type, invoices, currencies = [] }: { title: string; type: "sale" | "purchase"; invoices: any[]; currencies?: any[] }) { const [open, setOpen] = useState(false); const [currencyCode, setCurrencyCode] = useState("SAR"); const [exchangeRate, setExchangeRate] = useState("1"); const [selectedInvoice, setSelectedInvoice] = useState<number | undefined>(invoices[0]?.id); const [number, setNumber] = useState(`${type === "sale" ? "مبيعات" : "مشتريات"}-${Date.now().toString().slice(-5)}`); const [description, setDescription] = useState(""); const [quantity, setQuantity] = useState("1"); const [unitPrice, setUnitPrice] = useState(""); const [discount, setDiscount] = useState("0"); const [taxRate, setTaxRate] = useState("15"); const [paid, setPaid] = useState("0"); const create = trpc.invoices.create.useMutation({ onSuccess: () => { toast.success("تم حفظ الفاتورة"); setOpen(false); setDescription(""); setUnitPrice(""); }, onError: e => toast.error(e.message) }); const subtotal = Number(quantity || 0) * Number(unitPrice || 0); const tax = subtotal * Number(taxRate || 0) / 100; const total = Math.max(0, subtotal - Number(discount || 0) + tax); const baseTotal = total * Number(exchangeRate || 1); return <ModulePage title={title} description={type === "sale" ? "إدارة دورة المبيعات والتحصيل" : "إدارة دورة المشتريات والموردين"} icon={ReceiptText}><Card className="mb-4"><CardHeader className="flex-row items-center justify-between"><div><CardTitle>إنشاء فاتورة {type === "sale" ? "مبيعات" : "مشتريات"}</CardTitle><p className="text-sm text-muted-foreground">احسب الضريبة والخصم والدفع قبل الإصدار.</p></div><Button onClick={() => setOpen(!open)}>{open ? "إغلاق النموذج" : "فاتورة جديدة"}</Button></CardHeader>{open && <CardContent><div className="form-grid"><Input placeholder="رقم الفاتورة" value={number} onChange={e => setNumber(e.target.value)} /><Input placeholder="وصف الصنف" value={description} onChange={e => setDescription(e.target.value)} /><Input type="number" placeholder="الكمية" value={quantity} onChange={e => setQuantity(e.target.value)} /><Input type="number" placeholder="سعر الوحدة" value={unitPrice} onChange={e => setUnitPrice(e.target.value)} /><Input type="number" placeholder="الخصم" value={discount} onChange={e => setDiscount(e.target.value)} /><Input type="number" placeholder="نسبة الضريبة %" value={taxRate} onChange={e => setTaxRate(e.target.value)} /><Input type="number" placeholder="المدفوع" value={paid} onChange={e => setPaid(e.target.value)} /><select value={currencyCode} onChange={e => { const code = e.target.value; setCurrencyCode(code); setExchangeRate(String(currencies.find(c => c.code === code)?.exchangeRate ?? 1)); }}><option value="SAR">SAR — الريال السعودي</option>{currencies.filter(c => c.code !== "SAR").map(c => <option key={c.code} value={c.code}>{c.code} — {c.name}</option>)}</select><Input type="number" step="0.000001" placeholder="سعر الصرف مقابل SAR" value={exchangeRate} onChange={e => setExchangeRate(e.target.value)} /></div><div className="invoice-summary"><span>قبل الضريبة: {money(subtotal)} {currencyCode}</span><span>الضريبة: {money(tax)} {currencyCode}</span><strong>الإجمالي: {money(total)} {currencyCode}</strong><small>ما يعادله بالعملة الأساسية: {money(baseTotal)} SAR</small></div><Button disabled={!description.trim() || !Number(unitPrice) || create.isPending} onClick={() => create.mutate({ invoiceNumber: number, type, invoiceDate: new Date(), discount: Number(discount || 0), tax: tax, paid: Number(paid || 0), currencyCode, exchangeRate: Number(exchangeRate || 1), lines: [{ description, quantity: Number(quantity || 1), unitPrice: Number(unitPrice), taxRate: Number(taxRate || 0) }] })}>إصدار الفاتورة</Button></CardContent>}</Card><DocumentWorkflow /><DataTable headers={["رقم الفاتورة", "التاريخ", "الإجمالي", "المدفوع", "الحالة"]} rows={invoices.map(i => [i.invoiceNumber, new Date(i.invoiceDate).toLocaleDateString("ar-SA"), money(Number(i.total)), money(Number(i.paid)), i.status === "paid" ? "مدفوعة" : i.status === "overdue" ? "متأخرة" : "مستحقة"])} empty="لا توجد فواتير مسجلة بعد." /><div className="mt-4 flex flex-wrap items-center gap-3"><label className="text-sm font-medium">ربط المستند بالفاتورة</label><select value={selectedInvoice ?? 0} onChange={e => setSelectedInvoice(Number(e.target.value) || undefined)}><option value={0}>اختر فاتورة</option>{invoices.map(i => <option key={i.id} value={i.id}>{i.invoiceNumber}</option>)}</select></div><AttachmentUpload entityId={selectedInvoice} /></ModulePage>; }
function DocumentWorkflow() { const stages = ["مسودة", "مراجعة", "اعتماد", "ترحيل", "سداد", "أرشفة"]; return <Card className="mb-4"><CardHeader><CardTitle>الدورة المستندية المقترحة</CardTitle><p className="text-sm text-muted-foreground">طبّق التسلسل نفسه على الفواتير والقيود والمصروفات قبل اعتمادها نهائياً.</p></CardHeader><CardContent><div className="grid gap-2 sm:grid-cols-3 lg:grid-cols-6">{stages.map((stage, index) => <div key={stage} className="rounded-xl border bg-muted/40 p-3 text-center"><div className="mx-auto mb-2 flex h-7 w-7 items-center justify-center rounded-full bg-primary text-xs font-bold text-primary-foreground">{index + 1}</div><strong className="text-sm">{stage}</strong></div>)}</div></CardContent></Card>; }
function AttachmentUpload({ entityId }: { entityId?: number }) { const upload = trpc.attachments.upload.useMutation({ onSuccess: () => toast.success("تم رفع المستند وربطه بالسجل"), onError: e => toast.error(e.message) }); return <Card className="mt-4"><CardHeader><CardTitle>مرفقات المستندات</CardTitle><p className="text-sm text-muted-foreground">ارفع فاتورة أو إيصالاً بصيغة PDF أو صورة.</p></CardHeader><CardContent><Input type="file" disabled={!entityId || upload.isPending} onChange={event => { const file = event.target.files?.[0]; if (!file || !entityId) return; const reader = new FileReader(); reader.onload = () => { const data = String(reader.result).split(",")[1] ?? ""; upload.mutate({ entityType: "invoice", entityId, fileName: file.name, mimeType: file.type, data }); }; reader.readAsDataURL(file); }} />{!entityId && <p className="mt-2 text-xs text-muted-foreground">أنشئ فاتورة أولاً لتفعيل رفع المستندات.</p>}</CardContent></Card>; }
function StockMovePanel({ products }: { products: any[] }) { const [productId, setProductId] = useState(0); const [type, setType] = useState<"in" | "out">("in"); const [quantity, setQuantity] = useState(""); const move = trpc.stock.move.useMutation({ onSuccess: () => { toast.success("تم تسجيل حركة المخزون"); setQuantity(""); }, onError: e => toast.error(e.message) }); return <Card className="mb-4"><CardHeader><CardTitle>تسجيل حركة مخزون</CardTitle></CardHeader><CardContent><div className="form-grid"><select value={productId} onChange={e => setProductId(Number(e.target.value))}><option value={0}>اختر المنتج</option>{products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select><select value={type} onChange={e => setType(e.target.value as "in" | "out")}><option value="in">وارد</option><option value="out">صادر</option></select><Input type="number" placeholder="الكمية" value={quantity} onChange={e => setQuantity(e.target.value)} /></div><Button className="mt-4" disabled={!productId || !Number(quantity) || move.isPending} onClick={() => move.mutate({ productId, type, quantity: Number(quantity) })}>حفظ الحركة</Button></CardContent></Card>; }
function PayrollPanel() { const [period, setPeriod] = useState("2026-08"); const payroll = trpc.employees.payroll.useMutation({ onSuccess: () => toast.success("تم إنشاء كشف الرواتب"), onError: e => toast.error(e.message) }); return <Card className="mb-4"><CardHeader><CardTitle>إنشاء كشف رواتب شهري</CardTitle><p className="text-sm text-muted-foreground">يُحسب من رواتب الموظفين النشطين.</p></CardHeader><CardContent className="flex flex-wrap gap-3"><Input type="month" value={period} onChange={e => setPeriod(e.target.value)} /><Button disabled={!period || payroll.isPending} onClick={() => payroll.mutate({ period })}>إنشاء الكشف</Button></CardContent></Card>; }
function ReportPlaceholder({ title, text }: { title: string; text: string }) { return <div className="report-placeholder"><FileBarChart /><h3>{title}</h3><p>{text}</p><Button variant="outline">تحديد الفترة</Button></div>; }
function Reports({ summary, parties = [] }: { summary?: { revenue: number; expenses: number; profit: number; receivables: number }; parties?: any[] }) { const s = summary ?? { revenue: 0, expenses: 0, profit: 0, receivables: 0 }; const [reportType, setReportType] = useState<"financial" | "statement">("financial"); const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7)); const isStatement = reportType === "statement"; const title = isStatement ? "كشف حساب العملاء والموردين" : "التقرير المالي"; const rows = isStatement ? parties.map(p => ({ الحساب: p.name, النوع: p.type === "customer" ? "عميل" : "مورد", الرصيد_الافتتاحي: Number(p.openingBalance), حد_الائتمان: Number(p.creditLimit) })) : [{ البيان: "الإيرادات", المبلغ: s.revenue }, { البيان: "المصروفات", المبلغ: s.expenses }, { البيان: "صافي الربح", المبلغ: s.profit }, { البيان: "الذمم المدينة", المبلغ: s.receivables }]; const exportRows = rows.map(row => ({ الفترة: period, ...row })); const downloadPdf = () => { if (!exportToPdf(title, exportRows)) toast.error("يرجى السماح بالنوافذ المنبثقة لتصدير PDF"); }; return <section><div className="section-heading"><div className="section-icon"><FileBarChart /></div><div><h2>التقارير المالية</h2><p>رؤية واضحة للأداء وكشوف الحسابات</p></div><div className="export-actions"><select value={reportType} onChange={e => setReportType(e.target.value as "financial" | "statement")}><option value="financial">ملخص مالي</option><option value="statement">كشف حساب الأطراف</option></select><Input type="month" value={period} onChange={e => setPeriod(e.target.value)} /><Button variant="outline" size="sm" onClick={() => exportToExcel(title, exportRows)}>تصدير Excel</Button><Button size="sm" onClick={downloadPdf}>تصدير PDF</Button></div></div><div className="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard title="الإيرادات" value={money(s.revenue)} caption="من الفواتير المرحّلة" icon={ArrowUpRight} tone="green" /><MetricCard title="المصروفات" value={money(s.expenses)} caption="من فواتير المشتريات" icon={ArrowDownLeft} tone="orange" /><MetricCard title="الربح" value={money(s.profit)} caption="صافي الفترة الحالية" icon={CircleDollarSign} tone="purple" /><MetricCard title="الذمم" value={money(s.receivables)} caption="أرصدة العملاء" icon={WalletCards} tone="blue" /></div><div className="report-grid">{["الميزانية العمومية", "قائمة الدخل", "ميزان المراجعة", "الأستاذ العام", "التدفقات النقدية", "تقرير الضرائب"].map((r, i) => <Card key={r} className="report-card"><div className="report-number">0{i + 1}</div><FileBarChart /><h3>{r}</h3><p>عرض وتحليل التقرير حسب الفترة والحساب.</p><Button variant="outline" size="sm">فتح التقرير</Button></Card>)}</div></section>; }
function POS({ products, currencies = [] }: { products: any[]; currencies?: any[] }) { const [query, setQuery] = useState(""); const [currencyCode, setCurrencyCode] = useState("SAR"); const [cart, setCart] = useState<Array<{ product: any; quantity: number }>>([]); const createInvoice = trpc.invoices.create.useMutation({ onSuccess: () => { toast.success("تم إصدار فاتورة نقطة البيع"); setCart([]); }, onError: e => toast.error(e.message) }); const filtered = products.filter(p => p.name.includes(query) || p.sku.includes(query) || (p.barcode ?? "").includes(query)); const add = (product: any) => setCart(current => current.some(item => item.product.id === product.id) ? current.map(item => item.product.id === product.id ? { ...item, quantity: Math.min(Number(product.quantity), item.quantity + 1) } : item) : [...current, { product, quantity: 1 }]); const total = cart.reduce((s, item) => s + Number(item.product.salePrice) * item.quantity, 0); return <section><div className="section-heading"><div className="section-icon"><ScanBarcode /></div><div><h2>نقطة البيع</h2><p>بيع سريع وإصدار فوري للفواتير</p></div><Badge className="mr-auto">الجلسة مفتوحة</Badge></div><div className="pos-layout"><Card><CardHeader><div className="pos-search"><ScanBarcode /><Input autoFocus placeholder="امسح الباركود أو ابحث عن منتج..." value={query} onChange={e => setQuery(e.target.value)} /><Search /></div></CardHeader><CardContent><div className="product-grid">{filtered.map(p => <button key={p.id} className="product-tile" onClick={() => add(p)}><div className="product-image"><Package /></div><p>{p.name}</p><strong>{money(Number(p.salePrice))}</strong><small>{p.quantity} متوفر</small></button>)}</div>{!filtered.length && <div className="empty-state py-16"><Package /><p>لا توجد منتجات مطابقة</p></div>}</CardContent></Card><Card className="cart-card"><CardHeader><CardTitle>السلة الحالية ({cart.length})</CardTitle></CardHeader><CardContent>{cart.length ? <div className="cart-items">{cart.map(item => <div className="cart-item" key={item.product.id}><div><strong>{item.product.name}</strong><small>{money(Number(item.product.salePrice))}</small></div><div className="cart-controls"><button onClick={() => setCart(current => current.map(i => i.product.id === item.product.id ? { ...i, quantity: Math.max(1, i.quantity - 1) } : i))}>−</button><span>{item.quantity}</span><button onClick={() => add(item.product)}>+</button><button className="remove-cart" onClick={() => setCart(current => current.filter(i => i.product.id !== item.product.id))}>حذف</button></div></div>)}</div> : <div className="empty-state py-12"><ShoppingCart /><p>السلة فارغة</p><span>أضف المنتجات لإصدار الفاتورة</span></div>}<div className="cart-total"><span>الإجمالي</span><strong>{money(total)} {currencyCode}</strong></div><select className="mb-3 w-full" value={currencyCode} onChange={e => setCurrencyCode(e.target.value)}><option value="SAR">SAR — الريال السعودي</option>{currencies.filter(c => c.code !== "SAR").map(c => <option key={c.code} value={c.code}>{c.code} — {c.name}</option>)}</select><Button className="w-full" disabled={!cart.length || createInvoice.isPending} onClick={() => createInvoice.mutate({ invoiceNumber: `POS-${Date.now().toString().slice(-6)}`, type: "sale", invoiceDate: new Date(), discount: 0, tax: 0, paid: total, currencyCode, exchangeRate: Number(currencies.find(c => c.code === currencyCode)?.exchangeRate ?? 1), lines: cart.map(item => ({ productId: item.product.id, description: item.product.name, quantity: item.quantity, unitPrice: Number(item.product.salePrice), taxRate: 0 })) })}>إصدار الفاتورة</Button></CardContent></Card></div></section>; }
function Assistant() { const [question, setQuestion] = useState(""); const [sent, setSent] = useState<Array<{ question: string; answer?: string }>>([]); const ask = trpc.assistant.ask.useMutation({ onSuccess: data => setSent(current => current.map((item, index) => index === current.length - 1 && !item.answer ? { ...item, answer: data.answer } : item)), onError: () => toast.error("تعذر الوصول إلى المساعد حالياً") }); return <section><div className="assistant-hero"><div className="assistant-orb"><Sparkles /></div><div><p className="eyebrow">مدار AI</p><h2>مساعدك المحاسبي الذكي</h2><p>اسأل عن القيود والتقارير أو اطلب تصنيفاً أولياً لحركتك المالية.</p></div></div><div className="assistant-grid"><Card><CardHeader><CardTitle>ابدأ بسؤال</CardTitle></CardHeader><CardContent><div className="suggestion-row">{["كيف أقرأ قائمة الدخل؟", "اقترح قيد شراء بضاعة", "ما الفرق بين المدين والدائن؟"].map(s => <button key={s} onClick={() => setQuestion(s)}>{s}</button>)}</div><textarea className="assistant-input" placeholder="اكتب سؤالك المحاسبي هنا..." value={question} onChange={e => setQuestion(e.target.value)} /><Button disabled={ask.isPending} onClick={() => { const trimmed = question.trim(); if (trimmed) { setSent(current => [...current, { question: trimmed }]); ask.mutate({ question: trimmed }); setQuestion(""); } }}><Sparkles className="h-4 w-4" />{ask.isPending ? "جارٍ التحليل..." : "إرسال السؤال"}</Button></CardContent></Card><Card><CardHeader><CardTitle>المحادثة</CardTitle></CardHeader><CardContent>{sent.length ? sent.map((s, i) => <div className="chat-item" key={i}><div className="user-avatar">أ</div><div><p>{s.question}</p>{s.answer && <div className="assistant-answer">{s.answer}</div>}</div></div>) : <div className="empty-state py-12"><HelpCircle /><p>لم تبدأ المحادثة بعد</p><span>ستظهر الإجابات هنا عند تفعيل المساعد.</span></div>}</CardContent></Card></div></section>; }
function QuickTile({ icon: Icon, title, text, onClick }: { icon: typeof FilePlus2; title: string; text: string; onClick: () => void }) { return <button className="quick-tile" onClick={onClick}><div className="quick-tile-icon"><Icon /></div><div><strong>{title}</strong><span>{text}</span></div><ChevronLeft className="mr-auto" /></button>; }
function QuickAdd({ onClose, onAccount, onProduct, onParty }: { onClose: () => void; onAccount: (v: any) => void; onProduct: (v: any) => void; onParty: (v: any) => void }) { const [kind, setKind] = useState("account"); const [form, setForm] = useState<any>({ category: "asset", type: "customer", unit: "قطعة" }); const update = (key: string, value: string) => setForm((f: any) => ({ ...f, [key]: value })); return <div className="modal-backdrop"><Card className="quick-modal"><CardHeader className="flex-row items-center justify-between"><div><CardTitle>إضافة سجل جديد</CardTitle><p className="text-sm text-muted-foreground">أنشئ بيانات أولية بسرعة</p></div><button onClick={onClose}><X /></button></CardHeader><CardContent><div className="quick-tabs">{[["account", "حساب"], ["party", "عميل / مورد"], ["product", "منتج"]].map(([id, label]) => <button key={id} className={kind === id ? "active" : ""} onClick={() => setKind(id)}>{label}</button>)}</div>{kind === "account" && <div className="form-grid"><Input placeholder="رمز الحساب" value={form.code ?? ""} onChange={e => update("code", e.target.value)} /><Input placeholder="اسم الحساب" value={form.name ?? ""} onChange={e => update("name", e.target.value)} /><select value={form.category} onChange={e => update("category", e.target.value)}><option value="asset">أصول</option><option value="liability">التزامات</option><option value="equity">حقوق ملكية</option><option value="revenue">إيرادات</option><option value="expense">مصروفات</option></select></div>}{kind === "party" && <div className="form-grid"><Input placeholder="اسم العميل أو المورد" value={form.name ?? ""} onChange={e => update("name", e.target.value)} /><select value={form.type} onChange={e => update("type", e.target.value)}><option value="customer">عميل</option><option value="supplier">مورد</option></select><Input placeholder="رقم الهاتف" value={form.phone ?? ""} onChange={e => update("phone", e.target.value)} /><Input placeholder="حد الائتمان" type="number" value={form.creditLimit ?? ""} onChange={e => update("creditLimit", e.target.value)} /><Input placeholder="الرصيد الافتتاحي" type="number" value={form.openingBalance ?? ""} onChange={e => update("openingBalance", e.target.value)} /><select value={form.currencyCode ?? "SAR"} onChange={e => update("currencyCode", e.target.value)}><option value="SAR">SAR — الريال السعودي</option><option value="USD">USD — الدولار الأمريكي</option><option value="EUR">EUR — اليورو</option><option value="AED">AED — الدرهم الإماراتي</option></select></div>}{kind === "product" && <div className="form-grid"><Input placeholder="SKU" value={form.sku ?? ""} onChange={e => update("sku", e.target.value)} /><Input placeholder="اسم المنتج" value={form.name ?? ""} onChange={e => update("name", e.target.value)} /><Input placeholder="سعر البيع" type="number" value={form.salePrice ?? ""} onChange={e => update("salePrice", e.target.value)} /><Input placeholder="الكمية الافتتاحية" type="number" value={form.quantity ?? ""} onChange={e => update("quantity", e.target.value)} /><Input placeholder="الحد الأدنى للمخزون" type="number" value={form.minQuantity ?? ""} onChange={e => update("minQuantity", e.target.value)} /></div>}<Button className="mt-6 w-full" onClick={() => { if (kind === "account") onAccount(form); if (kind === "party") onParty(form); if (kind === "product") onProduct(form); }}><Plus className="h-4 w-4" />حفظ السجل</Button></CardContent></Card></div>; }

function EnhancedReports({ summary, parties, invoices, currencies }: { summary?: any; parties: any[]; invoices: any[]; currencies: any[] }) {
  const s = summary ?? { revenue: 0, expenses: 0, profit: 0, receivables: 0 };
  const [reportType, setReportType] = useState<"financial" | "statement" | "transactions">("financial");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [query, setQuery] = useState("");
  const [transactionType, setTransactionType] = useState<"all" | "sale" | "purchase">("all");
  const [minAmount, setMinAmount] = useState("");
  const [maxAmount, setMaxAmount] = useState("");
  const [currency, setCurrency] = useState("ALL");
  const filteredInvoices = invoices.filter(invoice => {
    const date = new Date(invoice.invoiceDate).getTime();
    const matchesFrom = !from || date >= new Date(`${from}T00:00:00`).getTime();
    const matchesTo = !to || date <= new Date(`${to}T23:59:59.999`).getTime();
    const amount = Number(invoice.total ?? 0);
    const matchesAmount = (!minAmount || amount >= Number(minAmount)) && (!maxAmount || amount <= Number(maxAmount));
    const matchesText = !query || `${invoice.invoiceNumber} ${invoice.notes ?? ""} ${invoice.type}`.toLowerCase().includes(query.toLowerCase());
    const matchesType = transactionType === "all" || invoice.type === transactionType;
    const matchesCurrency = currency === "ALL" || (invoice.currencyCode ?? "SAR") === currency;
    return matchesFrom && matchesTo && matchesAmount && matchesText && matchesCurrency && matchesType;
  });
  const chartData = [
    { name: "الإيرادات", value: Number(s.revenue) },
    { name: "المصروفات", value: Number(s.expenses) },
    { name: "الربح", value: Math.max(0, Number(s.profit)) },
    { name: "الذمم", value: Number(s.receivables) },
  ];
  const statementRows = parties.flatMap(p => { const partyInvoices = filteredInvoices.filter(i => Number(i.partyId) === Number(p.id)); let running = Number(p.openingBalance); const opening = { التاريخ: "الرصيد الافتتاحي", الحساب: p.name, النوع: p.type === "customer" ? "عميل" : "مورد", العملة: p.currencyCode ?? "SAR", مدين: running, دائن: 0, الرصيد: running }; const movements = partyInvoices.map(i => { const debit = i.type === "sale" ? Number(i.total) : 0; const credit = i.type === "purchase" ? Number(i.total) : 0; running += debit - credit; return { التاريخ: new Date(i.invoiceDate).toLocaleDateString("ar-SA"), الحساب: p.name, النوع: i.type === "sale" ? "بيع" : "شراء", العملة: i.currencyCode ?? "SAR", مدين: debit, دائن: credit, الرصيد: running }; }); return [opening, ...movements]; });
  const transactionRows = filteredInvoices.map(i => ({ التاريخ: new Date(i.invoiceDate).toLocaleDateString("ar-SA"), الرقم: i.invoiceNumber, النوع: i.type === "sale" ? "مبيعات" : "مشتريات", العملة: i.currencyCode ?? "SAR", المبلغ: Number(i.total), المدفوع: Number(i.paid), الحالة: i.status }));
  const exportRows = reportType === "statement" ? statementRows : reportType === "transactions" ? transactionRows : [{ الفترة: `${from || "البداية"} — ${to || "اليوم"}`, البيان: "الإيرادات", المبلغ: Number(s.revenue), العملة: currency }, { الفترة: `${from || "البداية"} — ${to || "اليوم"}`, البيان: "المصروفات", المبلغ: Number(s.expenses), العملة: currency }, { الفترة: `${from || "البداية"} — ${to || "اليوم"}`, البيان: "صافي الربح", المبلغ: Number(s.profit), العملة: currency }, { الفترة: `${from || "البداية"} — ${to || "اليوم"}`, البيان: "الذمم المدينة", المبلغ: Number(s.receivables), العملة: currency }];
  const title = reportType === "statement" ? "كشف حساب العملاء والموردين" : reportType === "transactions" ? "تقرير الحركات المالية" : "التقرير المالي العام";
  const updateFilter = (setter: (value: string) => void, value: string) => setter(value);
  return <section>
    <div className="section-heading"><div className="section-icon"><FileBarChart /></div><div><h2>التقارير المالية والتحليل</h2><p>تقارير محاسبية مرئية قابلة للتصفية والتصدير</p></div><div className="export-actions"><Button variant="outline" size="sm" onClick={() => exportToExcel(title, exportRows)}>Excel</Button><Button size="sm" onClick={() => { if (!exportToPdf(title, exportRows)) toast.error("يرجى السماح بالنوافذ المنبثقة لتصدير PDF"); }}>PDF</Button></div></div>
    <Card className="mb-5"><CardHeader><CardTitle>خيارات التقرير والتصفية المتقدمة</CardTitle></CardHeader><CardContent><div className="form-grid"><select value={reportType} onChange={e => setReportType(e.target.value as typeof reportType)}><option value="financial">التقارير المالية العامة</option><option value="statement">كشوف حساب العملاء والموردين</option><option value="transactions">الحركات المالية</option></select><select value={transactionType} onChange={e => setTransactionType(e.target.value as typeof transactionType)}><option value="all">كل أنواع الحركات</option><option value="sale">مبيعات</option><option value="purchase">مشتريات</option></select><select value={currency} onChange={e => setCurrency(e.target.value)}><option value="ALL">كل العملات</option>{currencies.map(c => <option key={c.code} value={c.code}>{c.code} — {c.name}</option>)}</select><Input type="date" value={from} onChange={e => updateFilter(setFrom, e.target.value)} /><Input type="date" value={to} onChange={e => updateFilter(setTo, e.target.value)} /><Input placeholder="بحث بالرقم أو الوصف" value={query} onChange={e => setQuery(e.target.value)} /><Input type="number" placeholder="من مبلغ" value={minAmount} onChange={e => setMinAmount(e.target.value)} /><Input type="number" placeholder="إلى مبلغ" value={maxAmount} onChange={e => setMaxAmount(e.target.value)} /></div><p className="mt-3 text-xs text-muted-foreground">يمكن الجمع بين الفترة والعملة ونطاق المبلغ والنص للوصول إلى الحركات المطلوبة بدقة.</p></CardContent></Card>
    <div className="mb-5 grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle>مؤشرات الأداء</CardTitle></CardHeader><CardContent><div className="h-72"><ResponsiveContainer width="100%" height="100%"><BarChart data={chartData}><CartesianGrid strokeDasharray="3 3" /><XAxis dataKey="name" /><YAxis /><Tooltip formatter={(value: number) => `${value.toLocaleString("ar-SA")} ${currency}`} /><Bar dataKey="value" fill="#3156d9" radius={[8, 8, 0, 0]} /></BarChart></ResponsiveContainer></div></CardContent></Card><Card><CardHeader><CardTitle>توزيع المؤشرات</CardTitle></CardHeader><CardContent><div className="h-72"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={chartData.slice(0, 3)} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={92} label>{chartData.slice(0, 3).map((entry, index) => <Cell key={entry.name} fill={["#36a269", "#e78b32", "#7455d9"][index]} />)}</Pie><Tooltip /><Legend /></PieChart></ResponsiveContainer></div></CardContent></Card></div>
    <div className="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard title="الإيرادات" value={money(Number(s.revenue))} caption="الفترة الحالية" icon={ArrowUpRight} tone="green" /><MetricCard title="المصروفات" value={money(Number(s.expenses))} caption="الفترة الحالية" icon={ArrowDownLeft} tone="orange" /><MetricCard title="صافي الربح" value={money(Number(s.profit))} caption="بعد المصروفات" icon={CircleDollarSign} tone="purple" /><MetricCard title="الذمم" value={money(Number(s.receivables))} caption="الأرصدة المستحقة" icon={WalletCards} tone="blue" /></div>
    {reportType === "financial" ? <div className="report-grid">{["الميزانية العمومية", "قائمة الدخل", "ميزان المراجعة", "الأستاذ العام", "التدفقات النقدية", "تقرير الضرائب"].map((r, i) => <Card key={r} className="report-card"><div className="report-number">0{i + 1}</div><FileBarChart /><h3>{r}</h3><p>افتح التقرير مع نفس الفترة والعملة المحددة أعلاه.</p><Button variant="outline" size="sm" onClick={() => { setReportType("transactions"); toast.info(`تم فتح تفاصيل ${r}`); }}>فتح التفاصيل</Button></Card>)}</div> : <DataTable headers={reportType === "statement" ? ["الفترة", "الحساب", "النوع", "العملة", "الرصيد الافتتاحي", "حد الائتمان"] : ["التاريخ", "الرقم", "النوع", "العملة", "المبلغ", "المدفوع", "الحالة"]} rows={(reportType === "statement" ? statementRows : transactionRows).map((row: any) => Object.values(row).map(value => typeof value === "number" ? String(value.toLocaleString("ar-SA")) : String(value)))} empty="لا توجد بيانات تطابق معايير البحث." />}
  </section>;
}

function SettingsAndImport({ currencies }: { currencies: any[] }) {
  const [preview, setPreview] = useState<{ accounts: any[]; parties: any[] }>({ accounts: [], parties: [] }); const [importErrors, setImportErrors] = useState<Array<{ row: number; field: string; message: string }>>([]);
  const updateRate = trpc.currencies.updateRate.useMutation({ onSuccess: () => toast.success("تم تحديث سعر الصرف"), onError: e => toast.error(e.message) });
  const commit = trpc.imports.masterData.useMutation({ onSuccess: result => { toast.success(`تم استيراد ${result.accountsImported + result.partiesImported} سجل بنجاح`); setImportErrors(result.errors ?? []); setPreview({ accounts: [], parties: [] }); }, onError: e => toast.error(e.message) });
  const parse = (file: File) => { const reader = new FileReader(); reader.onload = () => { const workbook = XLSX.read(reader.result, { type: "array" }); const rows = XLSX.utils.sheet_to_json<any>(workbook.Sheets[workbook.SheetNames[0]] ?? {}); const accounts = rows.filter(row => row["نوع السجل"] === "حساب" || row.type === "account").map(row => ({ code: String(row["كود الحساب"] ?? row.code ?? ""), name: String(row["اسم الحساب"] ?? row.name ?? ""), category: String(row["التصنيف"] ?? row.category ?? "asset"), openingBalance: Number(row["الرصيد الافتتاحي"] ?? row.openingBalance ?? 0) })); const parties = rows.filter(row => row["نوع السجل"] === "عميل" || row["نوع السجل"] === "مورد" || row.type === "customer" || row.type === "supplier").map(row => ({ type: (row["نوع السجل"] === "مورد" || row.type === "supplier" ? "supplier" : "customer") as "customer" | "supplier", name: String(row["الاسم"] ?? row.name ?? ""), phone: String(row["الهاتف"] ?? row.phone ?? ""), email: String(row["البريد الإلكتروني"] ?? row.email ?? ""), taxNumber: String(row["الرقم الضريبي"] ?? row.taxNumber ?? ""), openingBalance: Number(row["الرصيد الافتتاحي"] ?? row.openingBalance ?? 0), creditLimit: Number(row["حد الائتمان"] ?? row.creditLimit ?? 0), currencyCode: String(row["العملة"] ?? row.currencyCode ?? "SAR") })); setPreview({ accounts, parties }); }; reader.readAsArrayBuffer(file); };
  return <section><div className="section-heading"><div className="section-icon"><Settings2 /></div><div><h2>العملات والاستيراد</h2><p>إعداد العملات ونقل البيانات من أي نظام سابق بسرعة</p></div></div><Card className="mb-5"><CardHeader><CardTitle>العملات وأسعار الصرف</CardTitle></CardHeader><CardContent><div className="grid gap-3 md:grid-cols-2">{currencies.map(c => <div key={c.code} className="flex items-center gap-3 rounded-xl border p-3"><Badge>{c.code}</Badge><span className="flex-1">{c.name} ({c.symbol})</span><Input className="max-w-32" type="number" step="0.000001" defaultValue={c.exchangeRate} disabled={c.isBase} onBlur={e => !c.isBase && updateRate.mutate({ code: c.code, exchangeRate: Number(e.target.value) })} /><span className="text-xs text-muted-foreground">بالعملة الأساسية</span></div>)}</div></CardContent></Card><Card><CardHeader><CardTitle>استيراد العملاء والموردين والحسابات والأرصدة الافتتاحية</CardTitle><p className="text-sm text-muted-foreground">استخدم الأعمدة العربية: نوع السجل، الاسم، كود الحساب، اسم الحساب، التصنيف، الرصيد الافتتاحي، حد الائتمان، العملة.</p></CardHeader><CardContent><div className="flex flex-wrap gap-3"><Input type="file" accept=".xlsx,.xls" onChange={e => e.target.files?.[0] && parse(e.target.files[0])} /><Button variant="outline" onClick={() => exportToExcel("قالب-استيراد-البيانات", [{ "نوع السجل": "عميل", "الاسم": "", "الهاتف": "", "البريد الإلكتروني": "", "الرقم الضريبي": "", "كود الحساب": "", "اسم الحساب": "", "التصنيف": "asset", "الرصيد الافتتاحي": 0, "حد الائتمان": 0, "العملة": "SAR" }])}>تحميل قالب Excel</Button></div>{(preview.accounts.length + preview.parties.length) > 0 && <div className="mt-4 rounded-xl bg-muted p-4"><p className="font-semibold">معاينة آمنة قبل الإدخال: {preview.accounts.length} حساب و{preview.parties.length} عميل/مورد</p><Button className="mt-3" disabled={commit.isPending} onClick={() => commit.mutate(preview)}>اعتماد الاستيراد</Button></div>}{importErrors.length > 0 && <div className="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4 text-amber-900"><p className="font-semibold">صفوف تحتاج إلى مراجعة ({importErrors.length})</p><ul className="mt-2 list-disc pr-5 text-sm">{importErrors.map(error => <li key={`${error.row}-${error.field}`}>الصف {error.row} — {error.field}: {error.message}</li>)}</ul></div>}</CardContent></Card></section>;
}
